from itertools import groupby
from string import digits


def encode(text):
    """Encode runs, reserving ASCII digits for counts."""
    parts = []
    for char, run in groupby(text):
        if char in digits:
            raise ValueError("ASCII digits are reserved for counts")
        count = sum(1 for _ in run)
        if count > 1:
            parts.append(str(count))
        parts.append(char)
    return "".join(parts)


def decode(text):
    """Expand each optional count and its following character."""
    parts = []
    start = 0
    for index, char in enumerate(text):
        if char in digits:
            continue
        count = 1
        if start < index:
            if text[start] == "0":
                raise ValueError("count starts with zero")
            count = int(text[start:index])
            if count == 1:
                raise ValueError("single characters must omit the count")
        parts.append(char * count)
        start = index + 1
    if start < len(text):
        raise ValueError("count has no following character")
    return "".join(parts)
